 public void ExecuteSecure(Action action)
 {
    if (InvokeRequired)
    {
        //If the method is invoked from a thread other than the thread it was created on,
        //then the method will be called from the thread it was created on.
        //This is a problem because the thread it was created on is not the same as the thread
        //that is calling the method.
        //This is why we need to use the methodInvoker() method.
        //This method will call the method from the thread it was created on.
        //This is why we need to use the methodInvoker() method.
        action();
    }
    else
