            da.Fill(ds);
            if (ds.Tables[0].Rows.Count != 0)
            {
                gvOrder.DataSource = ds.Tables[0];
                gvOrder.DataBind();
            }
        }
    }
    catch (SqlException ex)
    {
        ExceptionHandling.SQLException(ex, constPageID, constIsSiteSpecific);
    }
}

